#!/usr/bin/env node
// Keeps PR descriptions fit to be squash commit messages (CLAUDE.md, Pull requests). Run by
// .github/workflows/pr-description.yml when a PR is opened or its description is edited: it removes the
// footers and trailers tools add at the end (a "Generated by/with Claude Code" line, a session link,
// Co-Authored-By and other trailers, the `---` above them), so a plain squash merge needs no hand editing.
// Needs GH_TOKEN (pull-requests: write), REPO (owner/name) and PR (the number). Plain Node, no dependencies.
import process from 'node:process';
import { pathToFileURL } from 'node:url';

/** Lines that are footers or trailers when they come at the end of a description. */
const FOOTER = [
  /^_?Generated (?:by|with) \[Claude Code\]\([^)]*\)_?$/i,
  /^🤖 Generated (?:by|with) \[Claude Code\]\([^)]*\)$/i,
  /^https:\/\/claude\.ai\/code\/\S+$/i,
  /^(?:Co-Authored-By|Claude-Session|Signed-off-by|Generated-by):.*$/i,
  /^-{3,}$/,
];

/** The description without the footer lines at its end (and the blank lines between them). */
export function stripFooter(body) {
  const lines = (body ?? '').replace(/\r\n/g, '\n').split('\n');
  let end = lines.length;
  while (end > 0) {
    const line = lines[end - 1].trim();
    if (line === '' || FOOTER.some((re) => re.test(line))) end -= 1;
    else break;
  }
  return lines.slice(0, end).join('\n');
}

async function main() {
  const { GH_TOKEN, REPO, PR } = process.env;
  if (!GH_TOKEN || !/^[\w.-]+\/[\w.-]+$/.test(REPO ?? '') || !/^\d+$/.test(PR ?? '')) {
    console.log('::error::GH_TOKEN, REPO and PR are required.');
    process.exit(1);
  }
  const url = `https://api.github.com/repos/${REPO}/pulls/${PR}`;
  const headers = {
    Authorization: `Bearer ${GH_TOKEN}`,
    Accept: 'application/vnd.github+json',
    'X-GitHub-Api-Version': '2022-11-28',
  };
  // Read the description fresh (not from the event), so a later edit is never overwritten.
  const res = await fetch(url, { headers, signal: AbortSignal.timeout(30_000) });
  if (!res.ok) throw new Error(`GET the PR: HTTP ${res.status}`);
  const { body } = await res.json();
  const cleaned = stripFooter(body);
  if (cleaned === (body ?? '').replace(/\r\n/g, '\n')) {
    console.log('The description has no footer to remove.');
    return;
  }
  const patch = await fetch(url, {
    method: 'PATCH',
    headers: { ...headers, 'Content-Type': 'application/json' },
    body: JSON.stringify({ body: cleaned }),
    signal: AbortSignal.timeout(30_000),
  });
  if (!patch.ok) throw new Error(`PATCH the PR: HTTP ${patch.status}`);
  console.log('Removed the footer from the description.');
}

// Run only as a script, not when a test imports stripFooter.
if (process.argv[1] !== undefined && import.meta.url === pathToFileURL(process.argv[1]).href) {
  await main();
}
